using CreatorEngine;

public sealed partial class KeyboardMover : Component
{
    public override void PostPhysics(float tick)
    {
        if (!HasTransform) return;
        if (Input.GetKey(KeyCode.W))
            Transform.Translate(Float3.Forward * (2f * tick));
    }
}

